const daniSide=["Zana","Lena","papa Jonathan","moeder Lana","zijn beste teamgenoot","coach Sam"];
const daniWeather=["frisse ochtendlucht","warme zon","dreigende wolken","harde wind","lichte regen","heldere sterrenhemel"];
const daniTwists=["Toen leek alles plotseling mis te gaan","Net op het moment dat Dani wilde versnellen","Vlak voor de belangrijkste actie","Iedereen keek naar Dani, maar hij keek juist om zich heen","De eerste oplossing werkte niet","Een onverwacht geluid veranderde de situatie"];

function daniStory(seed,level=3){
 const r=rng(hash("dani"+seed)),t=pick(r,daniThemes),side=pick(r,daniSide),weather=pick(r,daniWeather),twist=pick(r,daniTwists),focus=pick(r,["kijken, denken, doen","stoppen, ademen, kiezen","bal, ruimte, team","rust, richting, actie"]);
 const storyCode=hash(seed).toString(36).toUpperCase();
 const title=`Dani en ${t.title}`;
 const paras=[
 `De ${weather} hing boven ${t.place}. Op het digitale bord stond missiecode ${storyCode}. Dani trok zijn veters stevig aan. Vandaag wilde hij ${t.goal}. Hij voelde zich sterk, want hij had goed getraind en wist dat inzet vaak belangrijker is dan meteen alles perfect kunnen. ${side} gaf hem een boks en zei dat hij vooral goed moest blijven kijken.`,
 `Al snel ontstond er een probleem: ${t.problem}. Dani merkte dat zijn hoofd sneller wilde handelen dan verstandig was. Even dacht hij aan een glimmende sportauto die langs de lijn stond, aan een enge film en zelfs aan de vraag hoeveel pannenkoeken er in een voetbaltas zouden passen. Hij grinnikte. De Afleidings-Alien was weer langsgekomen.`,
 `${twist}. Dani drukte zijn duim tegen zijn wijsvinger, zijn geheime focusknop. Hij zei in zichzelf: “${focus}.” Daarna bekeek hij de situatie opnieuw. Toen zag hij dat ${t.clue}. Dat was geen toeval, maar een aanwijzing.`,
 `Dani overlegde kort met ${side}. Samen besloten ze ${t.plan}. De eerste poging lukte nog niet helemaal. In plaats van boos te worden, vroeg Dani zich af wat er precies misging. Hij veranderde één klein onderdeel van het plan en probeerde het opnieuw.`,
 `Nu werkte het wel. ${t.result}. Dani juichte, maar hij wist dat het succes niet alleen door kracht kwam. Hij had zijn aandacht teruggehaald, een patroon ontdekt en samengewerkt. Dat voelde bijna net zo goed als zelf het mooiste doelpunt maken.`,
 `Later thuis vertelde hij aan Lana en Jonathan wat er was gebeurd. Lena maakte er meteen een wild verhaal van waarin een haai, een dinosaurus en een keeper samen in een Lamborghini wegreden. Zana lachte. Dani schreef in zijn uitvindersboek: “Een doorzetter probeert niet blind hetzelfde. Hij kijkt wat er gebeurt en past zijn plan aan.”`
 ];
 const qs=[
  mc("Waar speelt het belangrijkste deel van het verhaal zich af?",t.place,daniThemes.filter(x=>x.place!==t.place).slice(0,3).map(x=>x.place),"De plaats wordt direct in de eerste alinea genoemd.","letterlijk"),
  mc("Wat was het belangrijkste probleem?",t.problem,daniThemes.filter(x=>x.problem!==t.problem).slice(0,3).map(x=>x.problem),"Dit probleem zorgt ervoor dat Dani zijn aanpak moet veranderen.","letterlijk"),
  mc("Welke aanwijzing hielp Dani verder?",t.clue,daniThemes.filter(x=>x.clue!==t.clue).slice(0,3).map(x=>x.clue),"Dani keek opnieuw en ontdekte dit patroon.","verband"),
  mc("Welke eigenschap laat Dani vooral zien?","Hij blijft rustig onderzoeken en past zijn plan aan.",["Hij wacht tot iemand anders alles oplost.","Hij gebruikt alleen zijn spierkracht.","Hij doet steeds precies hetzelfde zonder te kijken."],"Doorzetten betekent hier: leren van wat er gebeurt en gericht opnieuw proberen.","afleiden"),
  mc("Wat is de hoofdgedachte?","Goed kijken, samenwerken en bijsturen helpt bij een moeilijk probleem.",["De sterkste speler moet altijd zelf scoren.","Afleiding kan nooit worden gestopt.","Een wedstrijd is alleen leuk wanneer alles meteen lukt."],"Deze boodschap komt terug in het probleem, het plan en de afloop.","hoofdgedachte"),
  mc(`Wat betekent “${t.word[0]}” in deze tekst het best?`,vocabMeaning(t.word[0]),vocabDistractors(t.word[0]),`De betekenis past bij de manier waarop het woord in het verhaal wordt gebruikt.`,"woordenschat")
 ];
 return{title,story:paras.join("\n\n"),questions:qs,level,genre:"voetbalavontuur",estimatedWords:paras.join(" ").split(/\s+/).length,seed};
}
function vocabMeaning(w){const d={compact:"dicht bij elkaar",dapper:"moedig",aanwijzing:"iets dat helpt om een oplossing te vinden",onrust:"een toestand waarin mensen niet kalm zijn",concentratie:"je aandacht bij één ding houden",beslissend:"heel belangrijk voor de afloop",zwaartekracht:"de kracht die dingen naar een planeet trekt",voorspellen:"vooraf bedenken wat waarschijnlijk gebeurt",observeren:"aandachtig bekijken",voorzichtig:"met aandacht voor gevaar",innovatie:"een nieuwe nuttige uitvinding of aanpak",waarnemen:"met je zintuigen opmerken",beheersing:"jezelf rustig kunnen sturen",misleiden:"iemand iets anders laten denken",nauwkeurig:"heel precies",strategie:"een doordacht plan",sensor:"onderdeel dat iets in de omgeving meet",prototype:"eerste proefmodel",mechanisch:"werkend met een machine",reageren:"iets doen als antwoord op wat gebeurt",controle:"de situatie kunnen sturen",aanpassen:"veranderen zodat iets beter past",schaduw:"donkere vorm doordat licht wordt tegengehouden",systematisch:"volgens een vaste, slimme volgorde"};return d[w]||"precies passend bij de situatie"}
function vocabDistractors(w){return shuffle(rng(hash(w)),["zo hard mogelijk bewegen","zonder nadenken beginnen","iets dat alleen in een droom bestaat","een toevallig geluid"]);}

