const zanaRoles=["projectleider","kritische verslaggever","teamcaptain","junior-bestuurder","onderzoeker","onderhandelaar"];
const zanaComplications=["halverwege een nieuwe dataset verscheen","een belangrijke bron zijn eerdere uitspraak corrigeerde","de groep sterk verdeeld raakte","een deadline onverwacht werd vervroegd","een journalist een te eenvoudige conclusie publiceerde","een belanghebbende niet aan het eerste overleg had deelgenomen"];
const zanaOpeners=["Zana had geleerd dat een overtuigend antwoord niet automatisch een goed antwoord is.","De vergadering begon met een eenvoudige vraag die al snel ingewikkelder bleek.","Op papier leek de keuze overzichtelijk; in werkelijkheid botsten verschillende waarden.","Zana was niet de oudste deelnemer, maar wel degene die als eerste vroeg hoe de cijfers waren verzameld.","Iedereen wilde snel beslissen, terwijl Zana juist wilde weten welke aannames onder het voorstel lagen."];
function zanaStory(seed,level=5){
 const r=rng(hash("zana"+seed)),d=pick(r,zanaDomains),role=pick(r,zanaRoles),comp=pick(r,zanaComplications),open=pick(r,zanaOpeners);
 const storyCode=hash(seed).toString(36).toUpperCase();
 const title=`Zana en het dilemma van ${d.domain}`;
 const paras=[
 `${open} Het projectdossier droeg code ${storyCode}. Als ${role} werkte ze in ${d.setting} aan een vraagstuk: ${d.issue}. Het onderwerp paste bij haar ambitie om later leiding te geven, maar ze wist dat leiderschap niet betekent dat je als eerste het hardst praat. Het betekent dat je de juiste vragen stelt, belangen onderscheidt en verantwoordelijkheid neemt voor gevolgen die pas later zichtbaar worden.`,
 `De eerste presentatie leek duidelijk. Uit de cijfers bleek dat ${d.data}. Een deel van de groep wilde daarom onmiddellijk kiezen. Zana noteerde echter niet alleen de uitkomst, maar ook de gebruikte periode, de omvang van de onderzoeksgroep en wat buiten de meting was gebleven. Zij vroeg: “Wanneer noemen wij dit succes, voor wie, en over welke termijn?”`,
 `Die vraag veranderde het gesprek. De belangrijkste betrokkenen waren ${d.stake}. Hun belangen overlapten deels, maar niet volledig. Een oplossing kon financieel aantrekkelijk zijn en tegelijk extra risico of ongelijkheid veroorzaken. Zana maakte daarom een tabel met vier kolommen: voordeel, nadeel, onzekerheid en omkeerbaarheid. Een besluit dat later gemakkelijk kon worden aangepast, mocht volgens haar met iets meer onzekerheid worden getest dan een onomkeerbare keuze.`,
 `Vervolgens ontdekte ze een vertekening: ${d.bias}. Dat betekende niet automatisch dat de gepresenteerde informatie onwaar was. Wel betekende het dat de selectie van feiten de lezer in één richting kon duwen. Zana zocht de oorspronkelijke bron, controleerde definities en vergeleek de cijfers met een onafhankelijke publicatie.`,
 `Toen ${comp}, moest de groep opnieuw bepalen welke informatie zwaar woog. Sommige deelnemers vonden dat twijfel vooral vertraging veroorzaakte. Zana antwoordde dat zorgvuldig denken iets anders is dan eindeloos uitstellen. Zij stelde een beslisgrens voor: welke feiten moesten zeker zijn, welke onzekerheden konden worden gevolgd en bij welk signaal zou het besluit opnieuw worden bekeken?`,
 `Voordat de groep koos, formuleerde Zana bewust het sterkste tegenargument tegen haar eigen voorkeur. Dat vond ze ongemakkelijk, maar juist nuttig. Een plan wordt niet sterker doordat je kritiek ontwijkt; het wordt sterker wanneer je laat zien welke kritiek terecht is en welke aanvullende waarborgen nodig zijn. De groep onderzocht daarom ook een alternatief scenario waarin de omstandigheden ongunstiger uitpakten dan verwacht.`,
 `Ze bespraken vervolgens wie de kosten zou dragen wanneer het plan mislukte en wie het meeste voordeel kreeg wanneer het wel lukte. Die verdelingsvraag bleek minstens zo belangrijk als het gemiddelde resultaat. Een positieve totaalscore kon namelijk verbergen dat één groep vrijwel alle nadelen droeg. Zana stelde daarom voor om niet alleen gemiddelden, maar ook verschillen tussen groepen te rapporteren.`,
 `Op basis daarvan koos de groep ervoor ${d.decision}. De keuze was minder spectaculair dan het eerste voorstel, maar beter uitlegbaar. Bovendien bevatte het besluit vaste evaluatiemomenten. Zo kon de groep leren van de werkelijkheid in plaats van te doen alsof alle gevolgen vooraf bekend waren.`,
 `Na afloop schreef Zana in haar notitieboek dat het kernbegrip van deze opdracht “${d.concept}” was. Ze begreep dat volwassen keuzes zelden bestaan uit een simpele tegenstelling tussen goed en fout. Vaak gaat het om de kwaliteit van criteria, de betrouwbaarheid van informatie, de verdeling van voor- en nadelen en de bereidheid om een besluit bij te stellen zonder je oorspronkelijke doel te vergeten.`,
 `Thuis vroeg Dani of dit betekende dat je bij een penalty ook eerst een tabel moest maken. Zana lachte. “Nee, daar heb je soms maar één seconde. Maar juist daarom train je vooraf hoe je kijkt.” Lena stelde voor om alle moeilijke vergaderingen op te lossen met roze stickers. Zana vond dat eerlijk gezegd geen slecht idee: zelfs een serieus proces mocht overzichtelijk en menselijk blijven.`
 ];
 const qs=[
  mc("Welk centraal vraagstuk onderzoekt de tekst?",d.issue,zanaDomains.filter(x=>x.issue!==d.issue).slice(0,3).map(x=>x.issue),"Het vraagstuk wordt in de eerste alinea expliciet geïntroduceerd.","hoofdzaak"),
  mc("Waarom noteert Zana ook periode, onderzoeksgroep en ontbrekende informatie?","Om te beoordelen hoe sterk en algemeen geldig de conclusie is.",["Om de presentatie langer te maken.","Omdat cijfers zonder context altijd verboden zijn.","Om de betrokkenen te overtuigen zonder discussie."],"De kwaliteit van een conclusie hangt mede af van methode, context en beperkingen.","kritisch lezen"),
  mc("Welke vertekening wordt in de tekst genoemd?",d.bias,zanaDomains.filter(x=>x.bias!==d.bias).slice(0,3).map(x=>x.bias),"De tekst maakt onderscheid tussen onjuiste informatie en selectief gepresenteerde informatie.","bron"),
  mc("Wat is de functie van de tabel met voordeel, nadeel, onzekerheid en omkeerbaarheid?","De verschillende gevolgen en risico’s systematisch vergelijken.",["Eén belanghebbende automatisch gelijk geven.","Alle onzekerheid uit het besluit verwijderen.","Alleen financiële gevolgen berekenen."],"De tabel is een afwegingsinstrument, geen automatische uitkomst.","tekstverband"),
  mc("Welke uitspraak past het best bij Zana’s visie op zorgvuldig beslissen?","Je bepaalt vooraf welke onzekerheid acceptabel is en wanneer je opnieuw evalueert.",["Je wacht tot alle onzekerheid verdwenen is.","Je kiest altijd de snelste oplossing.","Je volgt zonder controle de populairste bron."],"De beslisgrens en evaluatiemomenten vormen de kern van haar aanpak.","inference"),
  mc(`Wat betekent “${d.concept}” hier het best?`,zanaConcept(d.concept),["een willekeurige mening zonder criteria","een truc om moeilijke vragen te vermijden","een garantie dat een keuze nooit fout kan gaan"],"De betekenis volgt uit de manier waarop het begrip in de afweging wordt gebruikt.","woordenschat"),
  mc("Welke tekststructuur overheerst?","Vraagstuk – informatie – kritiek – afweging – besluit – reflectie",["Chronologische biografie zonder argumenten","Instructie met alleen losse stappen","Beschrijving van één plaats zonder conclusie"],"De tekst bouwt een beredeneerd besluit op vanuit een dilemma.","structuur"),
  mc("Welke aanvullende bron zou het besluit het meest versterken?","Een onafhankelijke analyse die methode, aannames en verschillende scenario’s laat zien.",["Een korte advertentie van de partij die financieel voordeel heeft.","Een anonieme reactie zonder controleerbare details.","Een populaire video die alleen de conclusie herhaalt."],"Een controleerbare, onafhankelijke bron helpt methode en aannames te toetsen.","brongebruik")
 ];
 return{title,story:paras.join("\n\n"),questions:qs,level,genre:d.domain,estimatedWords:paras.join(" ").split(/\s+/).length,seed};
}
function zanaConcept(c){const d={tijdshorizon:"de periode waarover gevolgen worden beoordeeld",meetbaarheid:"de mate waarin iets betrouwbaar in cijfers of waarnemingen kan worden vastgelegd",proportionaliteit:"of een maatregel niet zwaarder is dan nodig voor het doel",onzekerheid:"wat nog niet voldoende bekend of bewezen is",bronverificatie:"controleren waar informatie vandaan komt en of die klopt",afwegingskader:"vooraf gekozen criteria waarmee opties worden vergeleken",risicobeheersing:"risico’s herkennen, beperken en blijven volgen",systeembenadering:"kijken hoe meerdere onderdelen elkaar beïnvloeden",verantwoordelijkheid:"zelf kunnen uitleggen en dragen waarom een keuze is gemaakt","duurzame prestatie":"goed presteren zonder ontwikkeling en gezondheid op langere termijn te beschadigen",representativiteit:"de mate waarin deelnemers een bredere groep werkelijk weerspiegelen",scenarioanalyse:"meerdere mogelijke toekomsten doorrekenen en vergelijken"};return d[c]||"een precies begrip voor een zorgvuldige keuze"}

