function lenaStory(seed,level=1){
 const r=rng(hash("lena"+seed)),s=pick(r,lenaScenes),number=2+Math.floor(r()*5),storyCode=hash(seed).toString(36).toUpperCase();
 const weather=pick(r,["De zon maakte gouden vlekjes op de grond.","Buiten tikte zachte regen tegen het raam.","Er waaide een vrolijke wind langs de vlaggetjes.","De lucht was roze en oranje.","Er lagen kleine plassen die glinsterden.","Een wolk leek precies op een konijn."]);
 const extra=pick(r,["Onderweg telde Lena drie vogels.","Lena vond een veertje met twee kleuren.","Een vlinder ging even op haar schoen zitten.","Ze hoorde ergens een grappig piepgeluid.","Op de grond lag een spoor van ronde steentjes.","Een klein belletje rinkelde precies vier keer."]);
 const ending=pick(r,["Daarna koos ze een roze sticker voor haar avonturenboek.","Ze maakte een tekening met een hele grote zon.","Ze gaf iedereen een zachte high five.","Ze zong een zelfbedacht overwinningsliedje.","Ze bouwde thuis het avontuur na met blokken.","Ze vertelde het verhaal nog een keer aan haar knuffel."]);
 const story=`${weather} Op haar avonturenkaart stond regenboogcode ${storyCode}. Lena ging naar ${s.place}. Daar zag ze ${s.friend}. “Kom je helpen?” vroeg haar nieuwe vriend. Samen wilden ze ${s.goal}. ${extra}

Eerst ging het goed. Lena keek, wees en telde rustig. Toen ontstond er een probleem: ${s.problem}. Lena stopte even. Ze dacht na en zei: “Ik probeer het nog een keer, maar nu langzaam.”

De oplossing was eenvoudig: ${s.solution}. Het lukte! Lena klapte ${number} keer in haar handen. Daarna deden ze een vrolijk dansje. “Kleine stapjes zijn ook echte stappen,” zei Lena.

Thuis vertelde ze Dani en Zana alles. Dani maakte er een stoer avontuur van en Zana tekende een mooie kaart. Lena koos zelf de kleuren. ${ending}`;
 return{title:s.title,story,questions:[mc("Waar was Lena?",s.place,lenaScenes.filter(x=>x.place!==s.place).slice(0,3).map(x=>x.place),"Dat hoor je aan het begin van het verhaal.","luisteren"),mc("Wat hielp Lena om het probleem op te lossen?",s.solution,lenaScenes.filter(x=>x.solution!==s.solution).slice(0,3).map(x=>x.solution),"Lena deed dit rustig en toen lukte het.","begrip"),mc(`Welk ding hoort bij dit verhaal?`,s.answer,s.items.filter(x=>x!==s.answer).concat(["trein"]),"Dit voorwerp speelt een duidelijke rol in het verhaal.","herkennen")],level,genre:"kleuteravontuur",estimatedWords:story.split(/\s+/).length,seed};
}

