function makeSpelling(profile,seed,count=12){const bank=profile==="dani"?spellingDani:profile==="zana"?spellingZana:spellingLena;const r=rng(hash(profile+seed+"spell"));let chosen=shuffle(r,bank);while(chosen.length<count)chosen=chosen.concat(shuffle(r,bank));return chosen.slice(0,count).map((x,i)=>({id:i,prompt:x[0],answer:x[1],options:shuffle(r,x[2]),explain:x[3],mode:i%4===1?"sentence":i%4===2?"rule":"choice"}));}

function mathQuestion(profile,level,r,i){
 const c=(prompt,answer,explain,options=null,kind="rekenen")=>({prompt,answer:String(answer).replace(".",","),explain,options:options?shuffle(r,options.map(String)):null,kind});
 if(profile==="lena"){
  const mode=i%6;if(mode===0){const n=2+Math.floor(r()*9);return c(`Hoeveel sterren zie je? ${"⭐".repeat(n)}`,n,"Tel één voor één en wijs mee.")}
  if(mode===1){const a=Math.floor(r()*6),b=Math.floor(r()*(6-a));return c(`${a} + ${b} = ?`,a+b,"Je mag de getallen met vingers of blokjes maken.")}
  if(mode===2){const a=3+Math.floor(r()*7),b=Math.floor(r()*Math.min(4,a+1));return c(`${a} − ${b} = ?`,a-b,"Begin bij het grootste getal en haal er één voor één af.")}
  if(mode===3){const a=1+Math.floor(r()*9),b=1+Math.floor(r()*9);return c(`Welk getal is groter: ${a} of ${b}?`,Math.max(a,b),"Het grootste getal hoort bij de grootste hoeveelheid.",[a,b])}
  if(mode===4){const seq=[1,2,3,4,5,6,7,8,9];const start=Math.floor(r()*5);return c(`Welk getal komt hierna? ${seq[start]}, ${seq[start+1]}, ${seq[start+2]}, ...`,seq[start+3],"Tel steeds één verder.")}
  return c("Welke vorm heeft geen hoek?","cirkel","Een cirkel is rond en heeft geen hoek.",["cirkel","vierkant","driehoek"]);
 }
 if(profile==="dani"){
  const mode=i%10;
  if(mode===0){const a=100+Math.floor(r()*800),b=20+Math.floor(r()*250);return c(`${a} + ${b} = ?`,a+b,"Tel eerst honderdtallen, daarna tientallen en eenheden.")}
  if(mode===1){const a=350+Math.floor(r()*600),b=40+Math.floor(r()*Math.min(350,a-20));return c(`${a} − ${b} = ?`,a-b,"Trek in handige stappen af en controleer met optellen.")}
  if(mode===2){const a=pick(r,[3,4,6,7,8,9]),b=2+Math.floor(r()*10);return c(`${a} × ${b} = ?`,a*b,`Gebruik de tafel van ${a}.`) }
  if(mode===3){const b=pick(r,[3,4,5,6,8,10]),q=2+Math.floor(r()*10);return c(`${b*q} ÷ ${b} = ?`,q,"Controleer door je antwoord weer te vermenigvuldigen.")}
  if(mode===4){const euro=pick(r,[20,25,30,50]),price=pick(r,[7.5,12.75,18.4,23.9]);const ans=(euro-price).toFixed(2);return c(`Je betaalt € ${euro.toFixed(2).replace(".",",")} voor iets van € ${price.toFixed(2).replace(".",",")}. Hoeveel krijg je terug?`,ans,"Trek de prijs af van het betaalde bedrag.")}
  if(mode===5){const h=pick(r,[14,15,16,17]),m=pick(r,[10,20,25,35,40]);const add=pick(r,[20,30,45,60]);let total=h*60+m+add;return c(`De training start om ${h}:${String(m).padStart(2,"0")} en duurt ${add} minuten. Hoe laat is hij klaar?`,`${Math.floor(total/60)}:${String(total%60).padStart(2,"0")}`,"Tel de minuten op; maak bij 60 minuten een nieuw uur.")}
  if(mode===6){const total=pick(r,[24,32,36,40,48]),den=pick(r,[2,3,4,6,8]);const valid=total%den===0?den:4;return c(`Wat is 1/${valid} van ${total}?`,total/valid,`Deel ${total} door ${valid}.`) }
  if(mode===7){const cm=pick(r,[125,230,345,480]);return c(`${cm} cm = hoeveel meter en centimeter?`,`${Math.floor(cm/100)} m ${cm%100} cm`,"100 centimeter is 1 meter.")}
  if(mode===8){const seats=pick(r,[6,8,9]),rows=pick(r,[4,5,7]);return c(`In een kleine tribune zijn ${rows} rijen met ${seats} stoelen. Hoeveel stoelen zijn er?`,rows*seats,"Aantal rijen × stoelen per rij.")}
  const start=2+Math.floor(r()*8),step=2+Math.floor(r()*8);return c(`Welk getal volgt? ${start}, ${start+step}, ${start+2*step}, ${start+3*step}, ...`,start+4*step,`Er komt steeds ${step} bij.`);
 }
 const mode=i%12;
 if(mode===0){const base=pick(r,[80,120,160,240,360]),pct=pick(r,[10,15,20,25,30,40]);return c(`Hoeveel is ${pct}% van ${base}?`,base*pct/100,"Bereken eerst 10% of gebruik een breuk.")}
 if(mode===1){const old=pick(r,[60,80,120,150,240]),pct=pick(r,[15,20,25,30]);return c(`Een product van € ${old.toFixed(2).replace(".",",")} krijgt ${pct}% korting. Wat is de nieuwe prijs?`,(old*(1-pct/100)).toFixed(2),"Bereken de korting en trek die af.")}
 if(mode===2){const den=pick(r,[4,5,8,10]),num=1+Math.floor(r()*(den-1)),total=den*pick(r,[6,8,12,15]);return c(`Bereken ${num}/${den} van ${total}.`,num*total/den,"Deel door de noemer en vermenigvuldig met de teller.")}
 if(mode===3){const a=pick(r,[1.25,2.4,3.75,6.8]),b=pick(r,[0.6,1.35,2.25,4.4]);return c(`${String(a).replace(".",",")} + ${String(b).replace(".",",")} = ?`,(a+b).toFixed(2),"Zet de komma’s onder elkaar.")}
 if(mode===4){const ratio=pick(r,[[2,3],[3,5],[4,7]]),factor=pick(r,[4,6,8]);return c(`De verhouding blauw : roze is ${ratio[0]} : ${ratio[1]}. Er zijn ${ratio[0]*factor} blauwe. Hoeveel roze zijn er?`,ratio[1]*factor,"Bepaal eerst met welke factor de verhouding is vermenigvuldigd.")}
 if(mode===5){const a=3+Math.floor(r()*9),b=a+5+Math.floor(r()*14);return c(`Los op: x + ${a} = ${b}.`,b-a,"Trek aan beide kanten hetzelfde getal af.")}
 if(mode===6){const l=pick(r,[6,8,12,15]),w=pick(r,[4,5,7,9]);return c(`Een rechthoek is ${l} cm lang en ${w} cm breed. Wat is de oppervlakte?`,l*w,"Oppervlakte = lengte × breedte.")}
 if(mode===7){const distance=pick(r,[60,90,120,150]),time=pick(r,[2,3,5]);const d=distance-(distance%time);return c(`Een trein rijdt ${d} km in ${time} uur. Wat is de gemiddelde snelheid?`,d/time,"Gemiddelde snelheid = afstand ÷ tijd.")}
 if(mode===8){const data=shuffle(r,[6,7,8,9,10]).slice(0,4);const sum=data.reduce((a,b)=>a+b,0);const fixed=sum%4===0?data:[6,8,10,12];return c(`Wat is het gemiddelde van ${fixed.join(", ")}?`,fixed.reduce((a,b)=>a+b,0)/4,"Tel alles op en deel door het aantal getallen.")}
 if(mode===9){const scale=pick(r,[100,200,500]),cm=pick(r,[3,4,6,8]);return c(`Op een kaart met schaal 1:${scale} is een afstand ${cm} cm. Hoeveel meter is dat echt?`,cm*scale/100,"Vermenigvuldig met de schaal en zet centimeters om in meters.")}
 if(mode===10){const start=pick(r,[120,250,400]),growth=pick(r,[5,10,20]);return c(`Een bedrag van € ${start} groeit één jaar met ${growth}%. Hoeveel is het daarna?`,(start*(1+growth/100)).toFixed(2),"Tel de procentuele groei bij het beginbedrag op.")}
 const n=pick(r,[3,4,5,6]);return c(`Welke uitkomst is gelijk aan ${n}²?`,n*n,"Een kwadraat is het getal maal zichzelf.",[n*2,n*n,n+n+1,n*n+1]);
}
function makeMath(profile,seed,count=20,level=3){const r=rng(hash(profile+seed+"math"));return Array.from({length:count},(_,i)=>mathQuestion(profile,level,r,i));}

